{"concept":"Transform YouTube into a glittering, hot-pink Barbie Dreamhouse dollhouse playset where videos rest inside plastic toy display packaging.","fingerprint":"retro pink dollhouse grid plastic shimmer","architecture":"restyle","needsHud":false,"hudReason":"","id":"3f170b87bbdc","name":"Barbie Dreamhouse Playset","dark":false,"bg":"#ffb6c1","surface":"#ffffff","surface2":"#ff69b4","fg":"#4a0e2e","ink":"#ff1493","accent":"#00ffff","remapSurfaces":false,"customCss":"@keyframes floatKen {
 0%, 100% { transform: translateY(0px) rotate(-0.75deg); }
 50% { transform: translateY(-6px) rotate(0.75deg); }
}
@keyframes glitterShimmer {
 0% { background-position: 0% 50%; }
 50% { background-position: 100% 50%; }
 100% { background-position: 0% 50%; }
}

html, body {
 background: #ffb6c1 url('data:image/svg+xml;utf8,<svg width="60" height="60" viewBox="0 0 60 60" xmlns="http://www.w3.org/2000/svg"><g fill="%23ff69b4" fill-opacity="0.18"><circle cx="15" cy="15" r="4"/><circle cx="45" cy="45" r="4"/><polygon points="30,5 33,12 40,15 33,18 30,25 27,18 20,15 27,12"/></g></svg>') repeat !important;
 color: #4a0e2e !important;
 font-family: 'Comic Sans MS', 'Arial Black', sans-serif !important;
 letter-spacing: 1.2px !important;
}

header, ytm-header-bar, .mobile-topbar-header {
 background: linear-gradient(135deg, #ff1493 0%, #ff69b4 50%, #00ffff 100%) !important;
 background-size: 200% 200% !important;
 animation: glitterShimmer 6s ease infinite !important;
 border-bottom: 5px solid #ffffff !important;
 box-shadow: 0 6px 20px rgba(255, 20, 147, 0.5) !important;
 padding: 8px 12px !important;
}

header *, ytm-header-bar * {
 color: #ffffff !important;
}

form, input.search-input, .c4-search-box-input {
 background: #ffffff !important;
 border: 3px solid #ff1493 !important;
 border-radius: 30px !important;
 color: #ff1493 !important;
 font-weight: 800 !important;
 font-family: 'Comic Sans MS', 'Arial Black', sans-serif !important;
 box-shadow: inset 0 2px 6px rgba(255, 105, 180, 0.3), 0 0 10px rgba(0, 255, 255, 0.4) !important;
 padding: 8px 14px !important;
}

input::placeholder {
 color: #ff69b4 !important;
 font-style: italic !important;
}

lazy-list, [data-mydes="grid"] {
 display: grid !important;
 grid-template-columns: repeat(2, 1fr) !important;
 gap: 16px !important;
 padding: 16px !important;
 box-sizing: border-box !important;
}

ytm-video-with-context-renderer.item.adaptive-feed-item, [data-mydes="card"] {
 display: flex !important;
 flex-direction: column !important;
 align-items: stretch !important;
 background: linear-gradient(135deg, #ffffff 0%, #ffe4e1 100%) !important;
 border: 4px solid #ff1493 !important;
 border-radius: 24px !important;
 box-shadow: inset 0 0 15px rgba(255, 105, 180, 0.5), 0 10px 25px rgba(74, 14, 46, 0.25) !important;
 overflow: hidden !important;
 animation: floatKen 4.5s ease-in-out infinite !important;
 transition: transform 0.2s cubic-bezier(0.34, 1.56, 0.64, 1), box-shadow 0.2s ease !important;
 margin: 0 !important;
 width: 100% !important;
 box-sizing: border-box !important;
 position: relative !important;
}

ytm-video-with-context-renderer.item.adaptive-feed-item:nth-child(even) {
 animation-delay: -2.25s !important;
}

ytm-video-with-context-renderer.item.adaptive-feed-item:active {
 transform: scale(0.97) !important;
 box-shadow: inset 0 0 25px #ff1493, 0 4px 10px rgba(74, 14, 46, 0.4) !important;
}

ytm-media-item {
 display: flex !important;
 flex-direction: column !important;
 width: 100% !important;
 height: 100% !important;
 padding: 8px !important;
 box-sizing: border-box !important;
}

.media-item-thumbnail-container, ytm-thumbnail-cover {
 width: 100% !important;
 border-radius: 16px !important;
 overflow: hidden !important;
 border: 3px dashed #ff69b4 !important;
 box-sizing: border-box !important;
 background: #ffe4e1 !important;
}

.media-item-thumbnail-container img, ytm-thumbnail-cover img {
 width: 100% !important;
 height: auto !important;
 display: block !important;
 object-fit: cover !important;
}

div.media-item-details {
 width: 100% !important;
 padding: 8px 4px 4px 4px !important;
 display: flex !important;
 flex-direction: column !important;
 box-sizing: border-box !important;
}

h3, .media-item-headline, .title {
 font-family: 'Comic Sans MS', 'Arial Black', sans-serif !important;
 font-size: 13px !important;
 font-weight: 900 !important;
 color: #ff1493 !important;
 text-transform: uppercase !important;
 letter-spacing: 0.8px !important;
 line-height: 1.3 !important;
 margin: 4px 0 !important;
 -webkit-line-clamp: 2 !important;
 display: -webkit-box !important;
 -webkit-box-orient: vertical !important;
 overflow: hidden !important;
 text-shadow: 1px 1px 0px #ffffff, 2px 2px 0px rgba(255, 105, 180, 0.3) !important;
}

.media-channel-title, .media-item-metadata, span.metadata-item {
 font-size: 10px !important;
 font-weight: 800 !important;
 color: #008b8b !important;
 text-transform: uppercase !important;
 margin-top: 2px !important;
}

yt-icon, .icon-button svg, button svg {
 fill: #ff1493 !important;
}

button, .yt-spec-button-shape-next {
 border-radius: 20px !important;
 background: linear-gradient(180deg, #ffffff 0%, #ff69b4 100%) !important;
 border: 2px solid #ff1493 !important;
 color: #ffffff !important;
 font-weight: 900 !important;
 text-shadow: 1px 1px 1px rgba(74, 14, 46, 0.6) !important;
 box-shadow: 0 4px 8px rgba(255, 20, 147, 0.3) !important;
}

div.ytGridShelfViewModelGridShelfRow.item {
 display: flex !important;
 gap: 12px !important;
 padding: 10px !important;
 overflow-x: auto !important;
}

div.ytGridShelfViewModelGridShelfItem {
 min-width: 140px !important;
 border: 3px solid #00ffff !important;
 border-radius: 18px !important;
 background: #ffffff !important;
 padding: 6px !important;
 box-shadow: 0 6px 15px rgba(0, 255, 255, 0.3) !important;
}","backdropHtml":"","hudHtml":"","customJs":"if (window.MydesBridge && typeof window.MydesBridge.enable3DTilt === 'function') {
 window.MydesBridge.enable3DTilt(1.2);
}"}
